package com.osminog.vision;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.Build;
import android.provider.Settings;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

/** APK updates only: HTTPS, bounded bytes, SHA-256, application ID, increasing
 * versionCode AND installed signing certificate. No downloaded executable JS. */
final class Updater {
 static final String FEED="https://raw.githubusercontent.com/jeep-jim/OSMINOG-Releases/main/channels/android-vision/dev.json";
 static final long MAX_APK=50L*1024*1024;
 final MainActivity a;final ExecutorService io=Executors.newSingleThreadExecutor();boolean busy=false,waitingPermission=false,closed=false;File pending;JSONObject available;
 Updater(MainActivity activity){a=activity;}
 static String sha(byte[] bytes)throws Exception{MessageDigest m=MessageDigest.getInstance("SHA-256");return hex(m.digest(bytes));}
 static String hex(byte[] bytes){StringBuilder b=new StringBuilder();for(byte x:bytes)b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}
 static boolean assetUrl(String value){try{URI u=new URI(value);return "https".equals(u.getScheme())&&"github.com".equals(u.getHost())&&u.getUserInfo()==null&&u.getPort()==-1&&u.getQuery()==null&&u.getFragment()==null&&u.getPath().startsWith("/jeep-jim/OSMINOG-Releases/releases/download/vision-android-v")&&u.getPath().endsWith(".apk");}catch(Exception e){return false;}}
 static void validate(JSONObject meta,int current)throws Exception{if(!"osminog-android-update/v1".equals(meta.optString("schema"))||!"com.osminog.vision".equals(meta.optString("applicationId")))throw new IOException("Канал предназначен для другого приложения");if(meta.optInt("versionCode",0)<1||meta.optLong("size",0)<1000||meta.optLong("size",0)>MAX_APK||!meta.optString("sha256").matches("[a-f0-9]{64}")||!assetUrl(meta.optString("apkUrl")))throw new IOException("Метаданные обновления повреждены");if(meta.optInt("minSdk",26)>Build.VERSION.SDK_INT)throw new IOException("Обновление требует более новой версии Android");}
 void share(){try{Intent intent=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"OSMINOG — установка для Android\nhttps://github.com/jeep-jim/OSMINOG-Releases/releases/tag/vision-android-v0.2.14");a.startActivity(Intent.createChooser(intent,"Поделиться установкой OSMINOG"));}catch(Exception e){a.notice("Не удалось открыть меню отправки ссылки.");}}
 void check(){if(busy||closed)return;busy=true;ui(()->a.notice("Проверяю канал обновлений…"));io.execute(()->{try{byte[] bytes=get(FEED+"?t="+System.currentTimeMillis(),128*1024,null);JSONObject m=new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));int current=a.getPackageManager().getPackageInfo(a.getPackageName(),0).versionCode;if("not-published".equals(m.optString("status"))){if(!"osminog-android-update/v1".equals(m.optString("schema"))||!"com.osminog.vision".equals(m.optString("applicationId")))throw new IOException("Канал обновлений повреждён");ui(()->{busy=false;a.notice("Канал обновлений ещё готовится.");});return;}validate(m,current);ui(()->{busy=false;if(m.optInt("versionCode")<=current){a.emit("updateCurrent","version",m.optString("versionName"));a.notice("Установлена актуальная OSMINOG Vision "+m.optString("versionName"));return;}available=m;String size=String.format(Locale.getDefault(),"%.1f КБ",m.optLong("size")/1024.0);a.emit("updateAvailable","versionName",m.optString("versionName"),"notes",m.optString("notes"),"sizeLabel",size);});}catch(Exception e){ui(()->{busy=false;a.notice("Не удалось проверить обновление: "+safe(e));});}});}
 void downloadAvailable(){JSONObject m=available;if(m==null){check();return;}download(m);}
 void download(JSONObject m){if(busy)return;busy=true;ui(()->a.emit("updateProgress","message","Скачиваю и проверяю APK…"));io.execute(()->{File part=new File(a.getCacheDir(),"update.part");try{get(m.getString("apkUrl"),m.getLong("size"),part);if(part.length()!=m.getLong("size"))throw new IOException("Размер APK не совпал");try(InputStream in=new FileInputStream(part)){MessageDigest digest=MessageDigest.getInstance("SHA-256");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)digest.update(buffer,0,n);if(!hex(digest.digest()).equals(m.getString("sha256")))throw new IOException("Контрольная сумма не совпала");}verifyPackage(part,m.getInt("versionCode"));File dest=new File(a.getCacheDir(),"update.apk");if(dest.exists()&&!dest.delete())throw new IOException("Невозможно подготовить установщик");if(!part.renameTo(dest))throw new IOException("Невозможно сохранить APK");ui(()->{busy=false;pending=dest;available=null;a.emit("updateReady","version",m.optString("versionName"));install();});}catch(Exception e){part.delete();ui(()->{busy=false;a.emit("updateProgress","message","Не удалось обновить: "+safe(e));a.notice("Обновление отменено: "+safe(e));});}});}
 void verifyPackage(File file,int expected)throws Exception{PackageManager pm=a.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo remote=pm.getPackageArchiveInfo(file.getAbsolutePath(),flags),local=pm.getPackageInfo(a.getPackageName(),flags);if(remote==null||!a.getPackageName().equals(remote.packageName)||remote.versionCode!=expected||remote.versionCode<=local.versionCode)throw new IOException("Неверное приложение или версия APK");android.content.pm.Signature[] x=Build.VERSION.SDK_INT>=28?remote.signingInfo.getApkContentsSigners():remote.signatures,y=Build.VERSION.SDK_INT>=28?local.signingInfo.getApkContentsSigners():local.signatures;if(x==null||y==null||x.length!=y.length||x.length==0)throw new IOException("Нет проверяемой подписи");Set<String> first=new HashSet<>(),second=new HashSet<>();for(android.content.pm.Signature s:x)first.add(sha(s.toByteArray()));for(android.content.pm.Signature s:y)second.add(sha(s.toByteArray()));if(!first.equals(second))throw new IOException("Подпись APK не совпадает с установленным OSMINOG");}
 void install(){if(pending==null||!pending.isFile()||!a.foreground)return;if(!a.getPackageManager().canRequestPackageInstalls()){waitingPermission=true;a.emit("installPermissionRequired");return;}waitingPermission=false;try{Uri uri=Uri.parse("content://"+a.getPackageName()+".updates/update.apk");Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(intent);a.notice("Подтверди установку в системном окне Android.");pending=null;}catch(Exception e){a.notice("Не удалось открыть установщик Android.");}}
 void resume(){if(pending!=null&&(!waitingPermission||a.getPackageManager().canRequestPackageInstalls()))install();}
 void openInstallSettings(){try{a.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));}catch(Exception e){a.notice("Не удалось открыть системные настройки установки.");}}
 byte[] get(String url,long limit,File target)throws Exception{URL next=new URL(url);HttpURLConnection c=null;for(int i=0;i<6;i++){String host=next.getHost();if(!"https".equals(next.getProtocol())||!(host.equals("raw.githubusercontent.com")||host.equals("github.com")||host.equals("release-assets.githubusercontent.com")||host.equals("objects.githubusercontent.com")))throw new IOException("Непроверенный адрес загрузки");c=(HttpURLConnection)next.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(45000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","OSMINOG-Vision-Android/0.2.2");int status=c.getResponseCode();if(status==301||status==302||status==303||status==307||status==308){String location=c.getHeaderField("Location");c.disconnect();next=new URL(next,location);continue;}if(status!=200){c.disconnect();throw new IOException("HTTP "+status);}long advertised=c.getContentLengthLong();if(advertised>limit){c.disconnect();throw new IOException("Загрузка превышает разрешённый размер");}ByteArrayOutputStream memory=target==null?new ByteArrayOutputStream():null;try(InputStream in=c.getInputStream();OutputStream out=target==null?memory:new FileOutputStream(target)){byte[] buffer=new byte[65536];long count=0;int n;while((n=in.read(buffer))!=-1){if(closed||Thread.currentThread().isInterrupted())throw new IOException("Загрузка остановлена");count+=n;if(count>limit)throw new IOException("Загрузка превышает разрешённый размер");out.write(buffer,0,n);}return memory==null?new byte[0]:memory.toByteArray();}finally{c.disconnect();}}throw new IOException("Слишком много перенаправлений");}
 String safe(Exception e){return e instanceof IOException?String.valueOf(e.getMessage()):"не пройдена проверка пакета";}
 void ui(Runnable r){a.runOnUiThread(()->{if(!closed&&!a.isFinishing()&&!a.isDestroyed())r.run();});}
 void close(){closed=true;io.shutdownNow();}
}
